+        throw new RuntimeException("Failed to connect to zookeeper (" + host + ") within 2x zookeeper timeout period " + timeout);
+      }

       if (tryAgain) {
         UtilWaitThread.sleep(sleepTime);
         if (sleepTime < 10000)
           sleepTime = (int) (sleepTime + sleepTime * Math.random());
       }
     }

     return zooKeeper;
